@Component
@Endpoint(id = "routes")                                  // GET /actuator/routes, POST /actuator/routes/{id}
public class RouteEndpoint {
    @ReadOperation public Map<String, String> all() { return routes.status(); }
    @WriteOperation public Map<String, Object> suspend(@Selector String id, String reason) {
        return Map.of("applied", routes.suspend(id, reason));
    }
}
